def f(n):
    loop_iters = 0
    adjust = 0
    if n <= 0:
        return 0, {'loop_iters': loop_iters, 'ceil_adjustments': adjust}
    if n == 1:
        return 6, {'loop_iters': loop_iters, 'ceil_adjustments': adjust}
    val = 12 * n - 3
    x = 0
    y = val
    root = 0
    while x <= y:
        loop_iters += 1
        m = (x + y) // 2
        p = m * m
        if p == val:
            root = m
            break
        if p < val:
            root = m
            x = m + 1
        else:
            y = m - 1
    if root * root < val:
        root += 1
        adjust = 1
    result = 2 * root
    return result, {'loop_iters': loop_iters, 'ceil_adjustments': adjust}

