    mod = 998244353
    edge_iterations = 0
    vertex_iterations = 0
    A = [0] * (n + 1)
    for x, y in lst:
        edge_iterations += 1
        A[x] += 1
        A[y] += 1
        if A[x] > 2 or A[y] > 2:
            return 0, {'edge_iterations': edge_iterations, 'vertex_iterations': vertex_iterations}
    val = 0
    val2 = 0
    for i in range(1, n + 1):
        vertex_iterations += 1
        if A[i] <= 1:
            val += 1
            if A[i] == 1:
                val2 += 1
    m = val * (val - 1) // 2
    res = m * (m - 1) // 2
    res2 = val2 * ((val - 1) * (val - 2) // 2)
    out = (res - res2) % mod
    return out, {'edge_iterations': edge_iterations, 'vertex_iterations': vertex_iterations}

