def f(n, arr):
    stats = {"segment_count": 0, "bit_operations": 0}
    d = {}
    lst = []
    for i, x in enumerate(arr, start=1):
        if x not in d:
            d[x] = i
        else:
            lst.append((d[x], i))
            stats["segment_count"] += 1
    lst.sort(key=lambda y: y[0])
    size = 2 * n
    bit = [0] * (size + 1)
    def bit_update(i, delta):
        stats["bit_operations"] += 1
        while i <= size:
            bit[i] += delta
            i += i & -i
    def bit_query(i):
        stats["bit_operations"] += 1
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s
    ans = 0
    for l, r in lst:
        ans += bit_query(r - 1) - bit_query(l)
        bit_update(r, 1)
    return ans, stats

