def f(x, A):
    n = len(A)
    arr = [-1] * (n + 1)
    arr[0] = x
    lst = sorted(A, key=lambda t: t[0])
    u = 0
    v = 0
    for y, z in lst:
        for k in range(n, 0, -1):
            u += 1
            if arr[k-1] >= y:
                m = arr[k-1] - y + z
                if m > arr[k]:
                    arr[k] = m
                    v += 1
    for k in range(n, -1, -1):
        if arr[k] >= 0:
            return k, {"iterations": u, "updates": v}
    return 0, {"iterations": u, "updates": v}

