def f(lst):
    c = 0
    d = 0
    if not lst:
        return 0, {"mult_checks": 0, "dp_updates": 0}
    n = max(lst)
    A = [0] * (n+1)
    for x in lst:
        A[x] += x
    B = A[:]
    res = 0
    for x in range(1, n+1):
        val = B[x]
        if val == 0:
            continue
        if val > res:
            res = val
        for m in range(2*x, n+1, x):
            c += 1
            if A[m] > 0:
                y = val + A[m]
                if y > B[m]:
                    B[m] = y
                    d += 1
    return res, {"mult_checks": c, "dp_updates": d}

