def f(x1: int, y1: int, x2: int, y2: int) -> tuple:
    sum_calls = 0
    max_depth = 0
    current_depth = 0
    cache = {}
    def g(n: int) -> int:
        nonlocal sum_calls, max_depth, current_depth
        sum_calls += 1
        current_depth += 1
        if current_depth > max_depth:
            max_depth = current_depth
        if n in cache:
            res = cache[n]
        else:
            if n < 10:
                res = n
            else:
                s = str(n)
                m = len(s) // 2
                n1 = int(s[:m])
                n2 = int(s[m:])
                res = g(n1) + g(n2)
            cache[n] = res
        current_depth -= 1
        return res
    def h(a: int, b: int) -> int:
        x = g(a)
        y = g(b)
        return x if x >= y else y
    v1 = h(x1, y1)
    v2 = h(x2, y2)
    if v1 > v2:
        r = '1'
    elif v1 < v2:
        r = '2'
    else:
        r = 'Draw'
    return r, {'sum_calls': sum_calls, 'max_depth': max_depth}

