def f(n, A):
    stats = {'calls': 0, 'key_iters': 0, 'merge_ops': 0}
    def helper(x, y):
        stats['calls'] += 1
        if y - x <= 1:
            return ({A[x]: 1}, 0)
        m = (x + y) // 2
        mp1, c1 = helper(x, m)
        mp2, c2 = helper(m, y)
        n1 = m - x
        n2 = y - m
        eq = 0
        stats['key_iters'] += len(mp1)
        for k, v in mp1.items():
            eq += v * mp2.get(k, 0)
        cu = n1 * n2 - eq
        if len(mp1) < len(mp2):
            mp_big, mp_small = mp2, mp1
        else:
            mp_big, mp_small = mp1, mp2
        stats['merge_ops'] += len(mp_small)
        for k, v in mp_small.items():
            mp_big[k] = mp_big.get(k, 0) + v
        return mp_big, c1 + c2 + cu
    if n <= 1:
        return 0, stats
    _, total = helper(0, n)
    return total, stats

