def f(n, m, A):
    B = sorted(A)
    C = [B[i+1] - B[i] for i in range(len(B) - 1)]
    if not C:
        return 0, {'oversized_gaps': 0, 'query_steps': 0}
    s = 1
    while s < len(C):
        s <<= 1
    T = [0] * (2 * s)
    c1 = 0
    for i, val in enumerate(C):
        if val > m:
            T[s + i] = (val - 1) // m
            c1 += 1
        else:
            T[s + i] = 0
    for j in range(s - 1, 0, -1):
        T[j] = T[2 * j] + T[2 * j + 1]
    cnt = 0
    def query(l, r):
        nonlocal cnt
        res = 0
        l += s
        r += s
        while l <= r:
            cnt += 1
            if l & 1:
                res += T[l]
                l += 1
            if not (r & 1):
                res += T[r]
                r -= 1
            l //= 2
            r //= 2
        return res
    out = query(0, len(C) - 1)
    return out, {'oversized_gaps': c1, 'query_steps': cnt}

