def f(n, m):
    stats = {'levels': 0, 'nodes': 0, 'swaps': 0}
    if n >= m:
        return (n - m, stats)
    lim = m * 2
    st1 = {n}
    st2 = {m}
    d1 = {n: 0}
    d2 = {m: 0}
    while st1:
        if len(st1) > len(st2):
            st1, st2 = st2, st1
            d1, d2 = d2, d1
            stats['swaps'] += 1
        stats['levels'] += 1
        st3 = set()
        for x in st1:
            val = d1[x]
            for y in (x - 1, x * 2):
                if 0 <= y <= lim and y not in d1:
                    if y in d2:
                        stats['nodes'] += 1
                        return (val + 1 + d2[y], stats)
                    d1[y] = val + 1
                    st3.add(y)
                    stats['nodes'] += 1
        st1 = st3
    return (-1, stats)

