def f(n, arr):
    L = [0] * n
    for i in range(1, n-1):
        if (arr[i] > arr[i-1] and arr[i] > arr[i+1]) or (arr[i] < arr[i-1] and arr[i] < arr[i+1]):
            L[i] = 1
    total = sum(L)
    trial_count = 0
    check_count = 0
    max_red = 0
    for i in range(1, n-1):
        orig = arr[i]
        cur_sum = L[i-1] + L[i] + L[i+1]
        best_imp = 0
        for val in (arr[i-1], arr[i+1]):
            trial_count += 1
            arr[i] = val
            new_sum = 0
            for j in (i-1, i, i+1):
                if 0 < j < n-1:
                    check_count += 1
                    if (arr[j] > arr[j-1] and arr[j] > arr[j+1]) or (arr[j] < arr[j-1] and arr[j] < arr[j+1]):
                        new_sum += 1
            imp = cur_sum - new_sum
            if imp > best_imp:
                best_imp = imp
        if best_imp > max_red:
            max_red = best_imp
        arr[i] = orig
    result = total - max_red
    return result, {"initial_hv": total, "modification_trials": trial_count, "hv_recomputations": check_count}

