def f(n, L):
    from math import gcd
    gcd_ops = 0
    res = []
    for arr in L:
        m = len(arr)
        ans = 0
        prev = {}
        for i in range(1, m):
            d = abs(arr[i] - arr[i-1])
            curr = {d: 1}
            for g, cnt in prev.items():
                gcd_ops += 1
                ng = gcd(g, d)
                curr[ng] = curr.get(ng, 0) + cnt
            for g, cnt in curr.items():
                if g != 1:
                    ans += cnt
            prev = curr
        res.append(ans)
    stats = {"gcd_ops": gcd_ops, "stable_subarrays": sum(res)}
    return res, stats

