    pop_ops = 0
    max_updates = 0
    if n < 2:
        return 0, {'pop_ops': pop_ops, 'max_updates': max_updates}
    val = 0
    lst = []
    for i in range(n):
        while lst and arr[lst[-1]] < arr[i]:
            lst.pop()
            pop_ops += 1
        if lst:
            cur = i - lst[-1] - 1
            if cur > val:
                val = cur
                max_updates += 1
        lst.append(i)
    lst.clear()
    for i in range(n - 1, -1, -1):
        while lst and arr[lst[-1]] < arr[i]:
            lst.pop()
            pop_ops += 1
        if lst:
            cur = lst[-1] - i - 1
            if cur > val:
                val = cur
                max_updates += 1
        lst.append(i)
    return val, {'pop_ops': pop_ops, 'max_updates': max_updates}

def f(A):
    from collections import Counter
    B = Counter(A)
    lst = sorted(B.keys())
    n = lst[-1]
    sum_trials = 0
    pointer_iterations = 0
    matches_found = 0
    res = 0
    for x in range(2, 2 * n + 1):
        sum_trials += 1
        pairs = 0
        i, j = 0, len(lst) - 1
        while i <= j:
            pointer_iterations += 1
            v1 = lst[i]
            v2 = lst[j]
            s = v1 + v2
            if s < x:
                i += 1
            elif s > x:
                j -= 1
            else:
                matches_found += 1
                if i < j:
                    pairs += min(B[v1], B[v2])
                else:
                    pairs += B[v1] // 2
                i += 1
                j -= 1
        if pairs > res:
            res = pairs
    return res, {"sum_trials": sum_trials, "pointer_iterations": pointer_iterations, "matches_found": matches_found}

