def f(n, k, arr):
    m = 0
    y = 0
    if n <= 1:
        val = arr[0] + min(k, 0) + k if n == 1 else 0
        return val, {'merges': m, 'dp_steps': y}
    L = [0] * (n - 1)
    for i in range(n - 1):
        x = arr[i] - arr[i+1] + 1
        L[i] = x if x > 0 else 0
    B = [[] for _ in range(k+2)]
    for p in range(n - 1):
        x = L[p] + 1
        if 1 <= x <= k:
            B[x].append(p)
    A = list(range(n))
    lst = list(range(n))
    def find(x):
        while A[x] != x:
            A[x] = A[A[x]]
            x = A[x]
        return x
    def union(u, v):
        nonlocal m
        ru = find(u)
        rv = find(v)
        if ru == rv:
            return
        A[rv] = ru
        if lst[rv] < lst[ru]:
            lst[ru] = lst[rv]
        m += 1
    dp1 = [0] * (n + 1)
    for stroke in range(1, k+1):
        for p in B[stroke]:
            union(p, p+1)
        dp2 = [0] * (n + 1)
        for i in range(1, n+1):
            root = find(i-1)
            val = i - lst[root]
            x = dp1[i] + val
            dp2[i] = dp2[i-1] if dp2[i-1] > x else x
            y += 1
        dp1 = dp2
    val = sum(arr) + dp1[n]
    return val, {'merges': m, 'dp_steps': y}

