def f(n, arr, x, y, k):
    import heapq
    A = [[] for _ in range(n)]
    B = [[] for _ in range(n)]
    for u, m, val in arr:
        A[u].append((m, val))
        B[m].append((u, val))
    INF = float('inf')
    L = [INF] * n
    L[y] = 0
    pq = [(0, y)]
    stat1 = 0
    while pq:
        dist, u = heapq.heappop(pq)
        if dist > L[u]:
            continue
        for m, val in B[u]:
            nd = dist + val
            if nd < L[m]:
                L[m] = nd
                stat1 += 1
                heapq.heappush(pq, (nd, m))
    lst = [0] * n
    pq = []
    heapq.heappush(pq, (L[x], 0, x))
    stat2 = 0
    while pq:
        fval, gval, u = heapq.heappop(pq)
        stat2 += 1
        lst[u] += 1
        if u == y and lst[u] == k:
            return gval, {'heuristic_updates': stat1, 'expand_count': stat2}
        if lst[u] > k:
            continue
        for m, val in A[u]:
            if L[m] == INF:
                continue
            newg = gval + val
            heapq.heappush(pq, (newg + L[m], newg, m))
    return -1, {'heuristic_updates': stat1, 'expand_count': stat2}

