def f(n, m, lst):
    from collections import deque
    INF = float('inf')
    x = 0
    y = 0
    A = [[] for _ in range(n)]
    for i, j in lst:
        if 0 <= i < n and 0 <= j < m:
            A[i].append(j)
    U = [-1] * n
    V = [-1] * m
    D = [0] * n

    def b():
        nonlocal x
        q = deque()
        for i in range(n):
            if U[i] == -1:
                D[i] = 0
                q.append(i)
            else:
                D[i] = INF
        found = False
        while q:
            i = q.popleft()
            for j in A[i]:
                x += 1
                w = V[j]
                if w != -1 and D[w] == INF:
                    D[w] = D[i] + 1
                    q.append(w)
                elif w == -1:
                    found = True
        return found

    def d(i):
        nonlocal y
