def f(n, s):
    val = n + 1
    A = [val] * n
    for x, text in enumerate(s):
        if text == 'a':
            A[x] = x
    ans = max(ord(text) - ord('a') for text in s)
    B = [val] * n
    levels = 0
    match_count = 0
    merge_count = 0
    for y in range(1, 26):
        C = [val] * (n + 1)
        for x in range(n - 1, -1, -1):
            C[x] = min(C[x + 1], A[x])
        any_valid = False
        str2 = chr(ord('a') + y)
        for x in range(n):
            if s[x] == str2:
                best = x
                match_count += 1
            else:
                best = val
            m = A[x]
            if m < n - 1:
                cand = C[m + 1]
                if cand < best:
                    best = cand
                    merge_count += 1
            B[x] = best
            if best < val:
                any_valid = True
        if not any_valid:
            break
        levels += 1
        if ans < y:
            ans = y
        A, B = B, [val] * n
    return ans + 1, dict(levels=levels, match_count=match_count, merge_count=merge_count)

