def f(lst):
    char_count = 0
    sort_comp = 0
    selections = 0
    n = len(lst)
    M = [[0]*5 for _ in range(n)]
    for x, s in enumerate(lst):
        for c in s:
            char_count += 1
            if 'a' <= c <= 'e':
                M[x][ord(c) - ord('a')] += 1
    def g(arr):
        nonlocal sort_comp
        if len(arr) <= 1:
            return arr
        m = len(arr) // 2
        A = g(arr[:m])
        B = g(arr[m:])
        x = 0
        y = 0
        C = []
        while x < len(A) and y < len(B):
            sort_comp += 1
            if A[x] > B[y]:
                C.append(A[x]); x += 1
            else:
                C.append(B[y]); y += 1
        if x < len(A):
            C.extend(A[x:])
        if y < len(B):
            C.extend(B[y:])
        return C
    res = 0
    for y in range(5):
        arr1 = []
        for x, s in enumerate(lst):
            cnt = M[x][y]
            diff = cnt - (len(s) - cnt)
            arr1.append(diff)
        arr2 = g(arr1)
        val_sum = 0
        cnt1 = 0
        for val in arr2:
            if val_sum + val <= 0:
                break
            val_sum += val
            cnt1 += 1
            selections += 1
        if cnt1 > res:
            res = cnt1
    return res, {"char_count": char_count, "sort_comp": sort_comp, "selections": selections}

