def f(L):
    union_calls = 0
    find_calls = 0
    connectivity_checks = 0
    res = []
    for A in L:
        if not A:
            res.append(True)
            continue
        mp = {}
        mp2 = {}
        d = {}
        st = set()
        flag = False
        for x, y in A:
            st.add(x)
            st.add(y)
            mp.setdefault(x, x)
            mp.setdefault(y, y)
            mp2.setdefault(x, 0)
            mp2.setdefault(y, 0)
            d.setdefault(x, 0)
            d.setdefault(y, 0)
        def find(a):
            nonlocal find_calls
            find_calls += 1
            if mp[a] != a:
                mp[a] = find(mp[a])
            return mp[a]
        def union(a, b):
            nonlocal union_calls
            union_calls += 1
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return False
            if mp2[ra] < mp2[rb]:
                mp[ra] = rb
            else:
                mp[rb] = ra
