def f(n, L, B):
    arr1 = [[] for _ in range(n)]
    arr2 = [[] for _ in range(n)]
    for x1, x2 in L:
        arr1[x1].append(x2)
        arr1[x2].append(x1)
    for x1, x2 in B:
        arr2[x1].append(x2)
        arr2[x2].append(x1)
    arr3 = [0] * n
    arr4 = [0] * n
    y = 0
    def dfs_euler(u, p):
        nonlocal y
        arr3[u] = y
        y += 1
        for w in arr2[u]:
            if w == p:
                continue
            dfs_euler(w, u)
        arr4[u] = y
    dfs_euler(0, -1)
    size = 1
    while size < n:
        size <<= 1
    st_max = [0] * (2 * size)
    st_lazy = [0] * (2 * size)
    def _apply(i, val_inner):
        st_max[i] += val_inner
        st_lazy[i] += val_inner
    def _push(i):
        v_inner = st_lazy[i]
        if v_inner:
            _apply(i * 2, v_inner)
            _apply(i * 2 + 1, v_inner)
            st_lazy[i] = 0
    def _update(i, l, r, ql, qr, val_inner):
        if qr <= l or r <= ql:
            return
        if ql <= l and r <= qr:
            _apply(i, val_inner)
            return
        _push(i)
        mid = (l + r) // 2
        _update(i * 2, l, mid, ql, qr, val_inner)
        _update(i * 2 + 1, mid, r, ql, qr, val_inner)
        st_max[i] = max(st_max[i * 2], st_max[i * 2 + 1])
    def range_add(l, r, val_inner):
        _update(1, 0, size, l, r, val_inner)
    def query_max():
        return st_max[1]
    removed = [False] * n
    arr5 = [0] * n
    best = 0
    stats = {'size_visits': 0, 'range_add_calls': 0, 'centroid_processed': 0}
    def dfs_sz(u, p):
        stats['size_visits'] += 1
        arr5[u] = 1
        for v in arr1[u]:
            if v == p or removed[v]:
                continue
            dfs_sz(v, u)
            arr5[u] += arr5[v]
    def find_centroid(u, p, tot):
        for v in arr1[u]:
            if v == p or removed[v]:
                continue
            if arr5[v] > tot // 2:
                return find_centroid(v, u, tot)
        return u
    def dfs_collect(u, p, col):
        col.append(u)
        for v in arr1[u]:
            if v == p or removed[v]:
                continue
            dfs_collect(v, u, col)
    def add_node(u):
        for g in arr2[u]:
            range_add(arr3[g], arr4[g], 1)
            stats['range_add_calls'] += 1
    def remove_node(u):
        for g in arr2[u]:
            range_add(arr3[g], arr4[g], -1)
            stats['range_add_calls'] += 1
    def process_centroid(c):
        nonlocal best
        stats['centroid_processed'] += 1
        rolled = []
        add_node(c)
        for v in arr1[c]:
            if removed[v]:
                continue
            part = []
            dfs_collect(v, c, part)
            for u in part:
                add_node(u)
            rolled.extend(part)
        curr = query_max()
        if curr > best:
            best = curr
        remove_node(c)
        for u in rolled:
            remove_node(u)
    def decompose(u):
        dfs_sz(u, -1)
        c = find_centroid(u, -1, arr5[u])
        process_centroid(c)
        removed[c] = True
        for v in arr1[c]:
            if not removed[v]:
                decompose(v)
    decompose(0)
    return best, stats

